WIDE = {"groupByKey", "reduceByKey", "join", "distinct", "repartition", "sortByKey"}

def plan_stages(ops):
    """ops: operation names in order, e.g. ["read", "map", "reduceByKey", "map"].
    Return the list of stages, each a list of operation names.
    A new stage starts at every wide operation."""
    stages = []
    for op in ops:
        if not stages or op in WIDE:
            stages.append([])
        stages[-1].append(op)
    return stages

