import zlib
from collections import defaultdict

def h(x):
    return zlib.crc32(str(x).encode())       # a stable hash

def distinct_users(events, hot, S, P):
    """events: a list of (product, user) pairs; hot: a set of hot products; S: salts per hot product;
    P: partitions. Return (counts, loads): counts maps each product to its number of distinct users;
    loads lists how many events each of the P partitions receives in the first shuffle, which sends
    an event whose shuffle key is k to partition h(k) % P."""
    parts = defaultdict(list)
    for product, user in events:
        parts[h(product) % P].append((product, user))     # all events of a product meet in one place
    counts = {}
    for rows in parts.values():
        users = defaultdict(set)
        for product, user in rows:
            users[product].add(user)
        counts.update({p: len(u) for p, u in users.items()})
    return counts, [len(parts[p]) for p in range(P)]

